const CARDS = [{"id": "m00", "name_en": "The Fool", "name_jp": "愚者", "arcana": "major", "number": 0, "keywords": ["新しい始まり", "自由", "無邪気さ", "可能性", "冒険", "未知", "信頼", "常識に縛られないこと"], "upright": "何にも縛られず、まっさらな気持ちで一歩を踏み出すとき。計画より直感を信じてみて。", "reversed": "考えなしの行動や、準備不足のまま飛び込むリスクを示すことも。", "love": "出会いの予感。損得抜きで惹かれる相手が現れるかも。", "img": "images/m00.jpg", "catchphrase": "まだ何者でもない。だからこそ、自由に一歩を踏み出せる。", "story": "崖の上に立つ愚者は、これから始まる長い旅の主人公。バッグ一つ、犬を連れて、恐れも計算もなく一歩を踏み出そうとしています。この時点では、彼はまだ何者でもありません。でもだからこそ、どんな可能性にも開かれている。愚者の旅は、ここから始まります。", "age_range": "10〜20代向け", "current_situation": "今のあなたは、何も決まっていない、まっさらな状態。新しい環境に飛び込んだばかりだったり、恋愛で言えば「出会ったばかりで、まだ何色にも染まっていない関係」だったりします。計画通りに進めるより、まず飛び込んでみている段階です。", "place": "旅行先や新しい習い事、引っ越し先など、まったく新しい環境での出会い。計画していたわけではないのに、飛び込んだ場所で自然に声をかけられるような、身軽なタイミングでの出会いです。", "symbols": [{"label": "白いバラ", "title": "胸元の白いバラ", "text": "手に持つ白いバラは、けがれのない純粋さを表しています。損得を考えない、まっさらな心のまま旅に出ようとしていることの象徴です。", "x": 73, "y": 32}, {"label": "白い服", "title": "身にまとう白い衣", "text": "純粋さ・無垢・素直さの象徴。まだ社会の常識や固定観念に染まりきっていないことを表しています。", "x": 45, "y": 45}, {"label": "崖っぷち", "title": "足元の崖", "text": "今にも踏み外しそうな崖の上に立つ姿は、目に見えないリスクをものともせず、無鉄砲に一歩を踏み出そうとする愚者の性質を表しています。未知の世界との境界であり、一歩先に何があるか分からないからこそ、踏み出す勇気がテーマになります。", "x": 48, "y": 79}, {"label": "白い犬", "title": "足元の白い犬", "text": "本能や忠実さを象徴する存在。愚者に寄り添い、時には危険を知らせる役割も持つとされ、直感や周囲からの警告を表すこともあります。", "x": 83, "y": 78}, {"label": "小さな荷物", "title": "杖にくくられた包み", "text": "必要最低限の荷物だけを持って旅立つ姿は、身軽さと、これまでの経験（すでに得た知恵）を最小限携えていることを示しています。", "x": 72, "y": 14}, {"label": "山", "title": "背景に連なる山々", "text": "これから向き合う未知の世界・試練を象徴しています。旅はまだ始まったばかりであることを表しています。", "x": 90, "y": 65}, {"label": "太陽", "title": "背景の太陽", "text": "光・生命力・可能性・意識の象徴。明るく開かれた未来を感じさせ、新しい始まりを祝福しています。", "x": 88, "y": 6}], "work": "計画よりまず動いてみたい時期。新しい仕事や役割にも、身軽な気持ちで飛び込んでみて。", "connections": {"next": "愚者「何も決まっていない。だから、何にでもなれる。」→ 魔術師「持っているものを使って、現実を創り始める。」"}}, {"id": "m01", "name_en": "The Magician", "name_jp": "魔術師", "arcana": "major", "number": 1, "keywords": ["創造力", "才能", "始動", "始まり", "コミュニケーション", "可能性", "自信", "自分の力を使う", "現実化"], "upright": "持っている力や道具を使いこなし、望むものを形にできるとき。行動力が結果を生む。", "reversed": "力の空回りや、口先だけで実行が伴わない状態。", "love": "自分から動くことで恋が動き出すサイン。アプローチは今が吉。", "work": "行動あるのみ。持っているスキルや人脈を総動員すれば、企画や提案が形になるとき。", "img": "images/m01.jpg", "catchphrase": "材料はもう揃っている。さあ、始めよう。", "story": "旅に出たばかりの愚者は、まず自分自身と出会います。魔術師は、火・水・風・地、すべての道具（ワンド・カップ・ソード・ペンタクル）を目の前に並べ、「これを使えば、なんでも創り出せる」と気づかせてくれる存在。行動する力はすでに自分の中にある——それを教えてくれる最初の出会いです。", "age_range": "20代向け", "current_situation": "今のあなたは、行動を起こせば結果につながる、力の乗った状態。気になる人にアプローチするか迷っているなら、動くべきタイミング。やる気はあるのに一歩を踏み出せていない、という状況かもしれません。", "place": "仕事関連の集まりやセミナー、スキルアップの場など、何かに向かって行動している場での出会い。共通の目的や熱量を持った相手と、自然に意気投合しやすいタイミングです。", "connections": {"prev": "愚者「何も決まっていない。だから、何にでもなれる。」→ 魔術師「持っているものを使って、現実を創り始める。」", "next": "魔術師「持っているものを使って、現実を創り始める。」→ 女教皇「外側だけではなく、自分の内側の声を聴く。」"}, "symbols": [{"label": "無限大マーク", "title": "頭上の無限大の記号（∞）", "text": "尽きることのない力、そして精神と物質がひとつにつながっていることを表す無限の象徴です。「あなたには、まだまだ可能性がある」というメッセージにつながります。", "x": 48, "y": 17}, {"label": "右手のワンド", "title": "右手に掲げたワンド（杖）", "text": "情熱・意志・行動力・創造力の象徴。自分の意志によって何かを始める力を表しています。", "x": 45, "y": 6}, {"label": "上下を向く手", "title": "天と地を指す両手", "text": "片方の手は天へ、もう片方は地面へ向けられています。天にあるアイデアや可能性を、地上の現実へ落とし込む——「天と地をつなぐ存在」としての魔術師を表しています。", "x": 80, "y": 53}, {"label": "4つの道具", "title": "テーブルの上のワンド・カップ・ソード・ペンタクル", "text": "小アルカナ4スートの象徴。ワンド＝行動、カップ＝感情、ソード＝思考、ペンタクル＝現実。魔術師はすでに、現実を動かすための材料をすべて持っています。", "x": 22, "y": 59}, {"label": "赤いバラ", "title": "足元に咲く赤いバラ", "text": "情熱・欲望・生命力・愛の象徴。「こうしたい」という生命力や情熱を表しています。", "x": 15, "y": 88}, {"label": "白いユリ", "title": "足元に咲く白いユリ", "text": "純粋さ・精神性・清らかさの象徴。赤いバラと合わせて、情熱と純粋さの両方を表しています。", "x": 50, "y": 86}, {"label": "緑の植物", "title": "足元の緑の植物", "text": "成長・生命力・豊かさ・発展の象徴。今始めたものが、これから育っていくイメージを表しています。", "x": 68, "y": 78}]}, {"id": "m02", "name_en": "The High Priestess", "name_jp": "女教皇", "arcana": "major", "number": 2, "keywords": ["直感", "静けさ", "内なる知恵", "潜在意識", "神秘", "見えない世界", "内面", "秘められた知識"], "upright": "焦って動くより、静かに内側の声を聞くべきとき。冷静な観察が答えをくれる。", "reversed": "秘密主義や、感情を閉ざしすぎている状態。", "love": "言葉より雰囲気で伝わる恋。焦らず様子を見るのが吉。", "work": "情報を集めるより、まず静かに状況を見極めて。焦って発言せず、内側の直感を信じたい局面。", "img": "images/m02.jpg", "catchphrase": "静かになって、自分の内側を感じてみよう。", "story": "次に愚者が出会うのは、多くを語らない女教皇。声高に教えるのではなく、静けさの中で「本当の答えは、自分の内側にある」と示してくれる存在です。まだ形になっていない直感や気づきを、急いで言葉にしなくていい。旅の中で、そんな余白の大切さを知る場面です。", "age_range": "20〜30代向け", "current_situation": "今のあなたは、口に出さずに様子を見ている段階。好きだと自覚していても、まだ誰にも言っていない、動きを起こさず静かに見守っている状態。焦って聞き出そうとするより、感じ取ることを大事にしているタイミングです。", "place": "オンラインでのやり取りや、共通の知人を介した間接的なつながりからの出会い。すぐに会うというより、まずメッセージのやり取りでじっくり距離を縮めていくような形になりそうです。", "connections": {"prev": "魔術師「持っているものを使って、現実を創り始める。」→ 女教皇「外側だけではなく、自分の内側の声を聴く。」", "next": "女教皇「外側だけではなく、自分の内側の声を聴く。」→ 女帝「愛情を注ぎ、豊かに育てる。」"}, "symbols": [{"label": "頭の冠", "title": "頭にある三日月形の冠", "text": "女神イシスの冠を思わせるもの。理屈や言葉ではなく、直感や感受性で物事をとらえる力を表しています。", "x": 50, "y": 12}, {"label": "黒い柱（B）", "title": "左側の黒い柱「B」", "text": "ソロモン神殿の柱ボアズに由来するとされます。闇・陰・受動性など、相反するものの一方を象徴するものとして読むことができます。", "x": 10, "y": 45}, {"label": "白い柱（J）", "title": "右側の白い柱「J」", "text": "ソロモン神殿の柱ヤキンに由来するとされます。光・陽・能動性など、黒い柱と対になるもう一方を象徴します。女教皇はその真ん中に座り、相反するものの奥にある真実を見る存在として描かれています。", "x": 90, "y": 45}, {"label": "巻物", "title": "膝の上に見える巻物", "text": "「TORA」の文字が見える巻物。神聖な知恵・秘められた知識・精神的な教えの象徴です。答えはすべて外に公開されるのではなく、自分の内側にあるものとして示されています。", "x": 52, "y": 58}, {"label": "ヤシの木", "title": "黒い柱の後ろのヤシの木", "text": "勝利・生命力・男性性・太陽といった、外へ伸びる力の象徴として読むことができます。", "x": 22, "y": 13}, {"label": "ザクロ", "title": "白い柱の後ろのザクロ", "text": "女性性・豊穣・生命・神秘の象徴。外側からは見えなくても、内側にはたくさんの種＝可能性が秘められているという意味を持ちます。", "x": 78, "y": 13}, {"label": "背後の水", "title": "衣の裾に表れる水の流れ", "text": "感情・潜在意識・直感・無意識の象徴。頭で考えるより、心の奥で感じているものに気づくことを表しています。", "x": 50, "y": 78}, {"label": "足元の三日月", "title": "足元に見える三日月", "text": "潜在意識・女性性・直感・神秘の象徴。女教皇のテーマそのものを強調しています。", "x": 50, "y": 87}, {"label": "青い衣装", "title": "身にまとう青い衣", "text": "静けさ・精神性・知性・冷静さの象徴。魔術師の赤い活動的なエネルギーとは対照的な色です。", "x": 48, "y": 60}]}, {"id": "m03", "name_en": "The Empress", "name_jp": "女帝", "arcana": "major", "number": 3, "keywords": ["豊かさ", "愛情", "母性", "生命", "豊穣", "美", "快楽", "創造", "育てること"], "upright": "満ち足りた愛情や豊かさが広がるとき。自分にも他人にも優しくできる時期。", "reversed": "甘やかしすぎや、依存気味の関係に注意。", "love": "愛され上手になれる時期。関係が深まり、安定に向かいやすい。", "work": "周囲との協力や、人を育てる役割で力を発揮できるとき。焦らず、豊かな実りを待って。", "img": "images/m03.jpg", "catchphrase": "愛情を注いで、豊かに育てる。", "story": "豊かな自然に囲まれた女帝との出会いは、愚者にとって初めて「満たされる」感覚を知る瞬間。与えられ、愛され、受け止めてもらう心地よさ。旅はここで、力だけでなく、愛情や豊かさもまた自分を育ててくれるのだと教えてくれます。", "age_range": "20〜40代向け", "place": "職場や友人の紹介など、居心地の良い環境の中で自然に距離が縮まる出会い。無理に探しに行くというより、日常生活の延長線上で縁がつながるタイミングです。", "current_situation": "今のあなたは、愛されることに満たされ、心にゆとりがある状態。恋愛でも自分磨きでも、無理をせず自然体でいられているタイミング。人からも大切にされていると感じやすい時期です。", "connections": {"prev": "女教皇「外側だけではなく、自分の内側の声を聴く。」→ 女帝「愛情を注ぎ、豊かに育てる。」", "next": "女帝「愛情を注ぎ、豊かに育てる。」→ 皇帝「守るために力を使い、秩序を作る。」"}, "symbols": [{"label": "12個の星の冠", "title": "頭にある12個の星の冠", "text": "12か月・12星座など、1年のサイクルや宇宙のリズムを象徴すると考えられます。自然のサイクルに従って、時間をかけて生命や物事を育てるイメージです。", "x": 48, "y": 8}, {"label": "女帝の王笏", "title": "右手に持つステッキ状の王笏", "text": "権威・生命を生み出す力・創造力・女性的な力の象徴。皇帝の「統率・秩序」とは異なる、愛情と生命力によって育てる力として読みます。", "x": 52, "y": 18}, {"label": "金星のマーク", "title": "足元の盾に描かれた金星の記号", "text": "愛と美の女神ヴィーナスの記号。愛情深さと、美を慈しむ感性、豊かさを受け取ることを表しています。", "x": 30, "y": 68}, {"label": "麦畑", "title": "足元に広がる黄金色の麦畑", "text": "豊穣・収穫・物質的豊かさ・成長の結果の象徴。育てたものが実を結ぶことを表しています。", "x": 50, "y": 88}, {"label": "森・緑", "title": "背景に広がる豊かな緑", "text": "生命力・自然・成長・豊かさの象徴。女帝そのものが「生命を育む自然」のような存在であることを表しています。", "x": 82, "y": 12}, {"label": "水の流れ", "title": "そばを流れる水", "text": "感情・愛情・生命力・豊かさの象徴。愛情を注ぐことで、生命や物事が育っていくという意味につながります。", "x": 88, "y": 55}, {"label": "ゆったりした衣服", "title": "ゆったりとした衣とクッション", "text": "妊娠・母性・女性の身体・生命を宿す力を連想させます。すでに豊かさの中にいて、それを受け取り、味わい、満たされているという姿勢を表しています。", "x": 55, "y": 62}, {"label": "王座", "title": "自然の中に置かれた王座", "text": "自ら奪いに行くというより、すでに豊かさの中でゆったりと受け取っている女帝の姿勢を表しています。", "x": 22, "y": 50}]}, {"id": "m04", "name_en": "The Emperor", "name_jp": "皇帝", "arcana": "major", "number": 4, "keywords": ["安定", "リーダーシップ", "責任", "権威", "統率", "秩序", "ルール", "防衛", "基盤", "現実的な力"], "upright": "自分で決め、責任を持って進める力があるとき。秩序と計画が成功を支える。", "reversed": "頑固さや支配的な態度が関係を硬直させることも。", "love": "頼れる相手、または頼られる自分。真剣な関係へ進みやすい。", "work": "責任あるポジションを任される、あるいは自分のやり方を貫くべきとき。秩序立てて計画を進めて。", "img": "images/m04.jpg", "catchphrase": "自分の力で秩序を作り、責任を持って世界を守る。", "story": "皇帝は、愚者に「秩序」と「責任」を示す存在。玉座にどっしりと座る姿は、自分で決め、自分の足で立つことの意味を教えてくれます。自由に旅してきた愚者が、初めて自分なりの枠組みやルールを持つことの大切さを学ぶ場面です。", "age_range": "30〜40代向け", "current_situation": "今のあなたは、自分のペースや条件を大事にしたい段階。相手に合わせすぎず、自分の生活や価値観を守りながら関係を築こうとしている状態。頼れる自分でいたい、という気持ちが強くなっているときです。", "place": "職場や、仕事に関連するつながりの中での出会い。安定した肩書きや役割がある環境で、頼れる相手・頼られる自分として自然に距離が縮まっていくタイミングです。", "connections": {"prev": "女帝「愛情を注ぎ、豊かに育てる。」→ 皇帝「守るために力を使い、秩序を作る。」", "next": "皇帝「守るために力を使い、秩序を作る。」→ 教皇「受け継いだ知恵を学び、人へ伝える。」"}, "symbols": [{"label": "王冠", "title": "頭にある王冠", "text": "権力・地位・支配者・責任の象徴。権力を持つということは、同時に責任も背負うということを表しています。", "x": 48, "y": 14}, {"label": "アンク（王笏）", "title": "右手に持つアンク型の王笏", "text": "古代エジプトで生命の象徴とされるアンク。生命を司る力と、世界を統率する力の両方を表しています。", "x": 23, "y": 30}, {"label": "左手の球体", "title": "左手に持つ球体", "text": "世界・領土・物質世界の象徴。自分の世界を管理し、秩序を保つことを表しています。", "x": 68, "y": 42}, {"label": "石の王座", "title": "石でできた王座", "text": "安定・強さ・固定されたもの・揺るがない基盤の象徴。簡単には揺らがない土台を作ることを表しています。", "x": 85, "y": 55}, {"label": "牡羊の頭", "title": "王座に彫られた4つの牡羊の頭", "text": "牡羊座の象徴で、行動力・開拓・勇気・リーダーシップを表します。皇帝の「自分から道を切り開く」性質とつながっています。", "x": 15, "y": 6}, {"label": "赤い衣装", "title": "身にまとう赤い衣", "text": "情熱・行動力・エネルギー・意志・力の象徴。女帝の柔らかい自然の色とは対照的に、「世界を動かす力」を強調しています。", "x": 48, "y": 45}, {"label": "鎧", "title": "衣の下にのぞく鎧", "text": "防衛・戦う準備・責任・守る力の象徴。皇帝は権力を持つだけでなく、「守る側」でもあることを表しています。", "x": 45, "y": 75}, {"label": "背景の岩山", "title": "玉座の向こうに広がる険しい岩山", "text": "試練・困難・揺るがない強さ・到達すべき目標の象徴。困難があっても責任を持って進む姿勢を表しています。", "x": 88, "y": 9}]}, {"id": "m05", "name_en": "The Hierophant", "name_jp": "教皇", "arcana": "major", "number": 5, "keywords": ["伝統", "助言", "信頼関係", "教育", "宗教", "信仰", "師弟関係", "継承", "制度", "集団"], "upright": "経験者からの助言や、王道のやり方が力になるとき。型を学ぶことに意味がある。", "reversed": "形式にとらわれすぎる、または助言を無視して孤立すること。", "love": "誠実で堅実な関係。周囲に祝福されるような恋の形。", "img": "images/m05.jpg", "catchphrase": "受け継がれてきた知恵を、人に教え、伝える人。", "story": "教皇との出会いは、旅の中で「一人で学ぶ」段階から「誰かに教わる」段階への移行を意味します。長く受け継がれてきた知恵や型を、素直に受け取ってみる。すべてを自己流で切り拓く必要はない、と気づかせてくれる存在です。", "age_range": "30代以上向け", "current_situation": "今のあなたは、誰か信頼できる人（先輩、上司、占い師、経験者）からのアドバイスを求めている、または実際に頼っている状況。一人で決めきれず、「王道のやり方」「みんなが通ってきた道」を知りたい気持ちが強くなっているとき。婚活で言えば、結婚相談所やマッチングアプリのような「型」に乗ってみている状態とも言えます。", "place": "婚活サービスや紹介、信頼できる人からのセッティングなど、きちんとした形での出会い。しっかりした段取りのある場で、誠実な相手と縁がつながりやすいタイミングです。", "symbols": [{"label": "三重の冠", "title": "頭にかぶる三重の冠（ティアラ）", "text": "精神・知性・物質という三つの世界を治める、大きな権威を表しています。「3」はキリスト教の三位一体（父・子・聖霊）を連想させます。ただしこの「精神・知性・物質」という読み方は、RWSの公式設定ではなく象徴的な応用解釈です。", "x": 50, "y": 8}, {"label": "三重の十字架", "title": "手にする杖の先端（三重十字）", "text": "3本の横棒を持つ十字は、宗教的権威・神聖な教えを象徴しています。", "x": 68, "y": 25}, {"label": "祝福のポーズ", "title": "右手の二本指を立てたポーズ", "text": "見える世界と見えない世界をつなぐ、祝福のジェスチャーです。魔術師も上と下をつなぐ動きをしますが、魔術師が「自分の可能性を現実化する」のに対し、教皇は「受け継いだ神聖な教えを人へ伝える」存在として描かれています。", "x": 32, "y": 25}, {"label": "左の柱", "title": "左側に立つ石の柱", "text": "宗教的・制度的な空間を表しています。女教皇の柱が「秘密の知恵・相反するものの間」を表すのに対し、教皇の柱は「社会の中で受け継がれる教え・制度」を象徴します。", "x": 8, "y": 40}, {"label": "右の柱", "title": "右側に立つ石の柱", "text": "左の柱と対になり、伝統や制度によって支えられた、教えの場としての秩序を表しています。", "x": 92, "y": 40}, {"label": "跪く二人", "title": "足元に跪く二人の人物", "text": "教えを受け継ぐ弟子の姿。教師と生徒、師弟関係、知恵や伝統が次の世代へと受け継がれていく様子を表しています。", "x": 25, "y": 78}, {"label": "交差した鍵", "title": "足元に置かれた交差する鍵", "text": "聖ペテロに授けられたとされる「天国の鍵」。神聖な教えや、神とのつながりへ入るための入口を象徴しています。なお、この2本の鍵は「弟子が2人いるから2本」というわけではなく、それぞれ独立した象徴として読みます。", "x": 50, "y": 88}], "work": "経験者のやり方や会社のルールに素直に従うと、うまく回り出すとき。我流より王道が近道。", "connections": {"prev": "皇帝「守るために力を使い、秩序を作る。」→ 教皇「受け継いだ知恵を学び、人へ伝える。」", "next": "教皇「受け継いだ知恵を学び、人へ伝える。」→ 恋人「自分自身の価値観で、何を選ぶか決める。」"}}, {"id": "m06", "name_en": "The Lovers", "name_jp": "恋人", "arcana": "major", "number": 6, "keywords": ["選択", "調和", "惹かれ合い", "愛", "恋愛", "価値観", "結びつき", "決断", "パートナーシップ"], "upright": "心から惹かれ合う関係や、価値観の合う相手との調和。素直な気持ちを大切に。", "reversed": "気持ちのすれ違いや、優柔不断による選択の迷い。", "love": "恋愛運の中でも特に良いカード。両想い・進展のサイン。", "img": "images/m06.jpg", "catchphrase": "心から望むものを選び、その選択に自分の意志で向き合う。", "story": "恋人のカードで、愚者は初めて大きな「選択」に直面します。何を大切にしたいのか、誰と歩いていきたいのか。理屈ではなく、心から惹かれるものを選ぶ経験が、この先の旅の方向を決めていきます。", "age_range": "10〜30代向け", "current_situation": "今のあなたは、まさに「選択」の真っ只中。複数の気持ちや選択肢の間で揺れていたり、告白しようか迷っていたり。頭で考えるより、心が惹かれる方に素直になれるかどうかが問われているタイミングです。", "place": "共通の友人を介した紹介、サークルや趣味のつながりなど、自然な形での出会い。合コンや婚活イベントよりも、気づいたら距離が縮まっていた……というような、フラットな関係性から始まる出会いが多いタイミングです。", "symbols": [{"label": "天使", "title": "上空に描かれる天使", "text": "大天使ラファエルとされ、癒しと導きを与える存在。男女の関係を、単なる欲望からより高い愛へと導く存在として描かれています。", "x": 50, "y": 15}, {"label": "太陽", "title": "天使の後ろに輝く太陽", "text": "光・真実・意識・生命力の象徴。自分の本心を照らすことを表しています。", "x": 50, "y": 5}, {"label": "山", "title": "二人の間に見える山", "text": "課題・障害・乗り越えるものの象徴。愛だけでなく、関係を選ぶなら向き合う課題があることを表しています。", "x": 50, "y": 76}, {"label": "女性側の木と蛇", "title": "女性の後ろの木に巻きつく蛇", "text": "エデンの園を連想させる情景。誘惑・知識・欲望・選択の象徴です。", "x": 15, "y": 40}, {"label": "男性側の燃える木", "title": "男性の後ろに描かれた炎をまとう木", "text": "情熱・欲望・行動力・生命エネルギーの象徴。女性側の「知識」と男性側の「情熱」、その両方を経験した上で「何を選ぶか」がこのカードのテーマになります。", "x": 85, "y": 40}], "work": "複数の選択肢で迷うとき。条件よりも、自分が心から納得できる方を選んで。", "connections": {"prev": "教皇「受け継いだ知恵を学び、人へ伝える。」→ 恋人「自分自身の価値観で、何を選ぶか決める。」", "next": "恋人「自分自身の価値観で、何を選ぶか決める。」→ 戦車「決めた道を、自分の意志で進む。」"}}, {"id": "m07", "name_en": "The Chariot", "name_jp": "戦車", "arcana": "major", "number": 7, "keywords": ["前進", "勝利", "意志の力", "自己コントロール", "突破"], "upright": "強い意志でまっすぐ突き進み、目標を勝ち取れるとき。勢いに乗ろう。", "reversed": "方向性を見失った暴走や、周囲との衝突に注意。", "love": "積極的なアプローチが実を結ぶ。押しの強さが吉と出る時期。", "img": "images/m07.jpg", "catchphrase": "決めた。自分の意志で、この道を進む。", "story": "選択を終えた愚者は、戦車に乗り込み、迷いを振り切って前進を始めます。二頭の異なるスフィンクスを御することは、相反する気持ちを一つの意志でまとめること。行き先が定まったなら、あとは進むだけだと教えてくれる場面です。", "age_range": "20〜30代向け", "current_situation": "今のあなたは、迷いを振り切って前に進もうとしている状態。告白する、距離を縮める、関係をはっきりさせるなど、勢いに乗って動き出しているタイミング。周りの目より、自分の意志を優先したい時期です。", "place": "スポーツ観戦やアクティビティ系のイベント、勢いのある集まりでの出会い。スピード感のある展開になりやすく、出会ってからすぐに距離が縮まるタイミングです。", "symbols": [{"label": "星の天蓋", "title": "頭上に広がる星模様の天蓋", "text": "宇宙的な守護、天からの導きを受けていることを示しています。", "x": 50, "y": 6}, {"label": "頭の冠", "title": "頭にかぶる冠", "text": "権威・自信・意志の象徴。自分の人生を自分の意志で動かす人物であることを表しています。", "x": 50, "y": 15}, {"label": "肩の三日月", "title": "両肩についた三日月の飾り", "text": "月・感情・無意識・直感を象徴しています。", "x": 25, "y": 30}, {"label": "胸元の四角", "title": "鎧の胸にある四角い意匠", "text": "安定・現実・土台の象徴。勢いだけでなく、自分の中心を持って進むことを表しています。", "x": 50, "y": 42}, {"label": "盾の翼のある球", "title": "腰の盾に描かれた紋章", "text": "均衡と勝利、精神が高く飛翔していく力を表しています。", "x": 50, "y": 58}, {"label": "手綱のない手", "title": "手綱を持たない両手", "text": "力ずくで引っ張るのではなく、確固たる意志の力だけで戦車を統率していることを示しています。", "x": 25, "y": 50}, {"label": "二頭のスフィンクス", "title": "戦車を引く黒と白のスフィンクス", "text": "相反する二つの力（白と黒、光と闇、理性と本能）を象徴します。重要なのは、この相反する力を手綱なしで一つの方向へまとめていることです。スフィンクスはまた、知恵・謎・試練の象徴でもあり、単純な力ではなく知恵と意志で力を扱うことを表しています。", "x": 35, "y": 80}, {"label": "後ろの街", "title": "背景に見える城壁の街", "text": "今まで過ごしてきた場所、安全な場所の象徴。そこから外の世界へ進んでいこうとしていることを表しています。", "x": 85, "y": 40}], "work": "勢いとスピード感がものを言うとき。迷いを断ち切って、決めた方向へ突き進んで。", "connections": {"prev": "恋人「自分自身の価値観で、何を選ぶか決める。」→ 戦車「決めた道を、自分の意志で進む。」", "next": "戦車「決めた道を、自分の意志で進む。」→ 力「外側だけでなく、自分の内側の本能も扱えるようになる。」"}}, {"id": "m08", "name_en": "Strength", "name_jp": "力", "arcana": "major", "number": 8, "keywords": ["内なる強さ", "忍耐", "優しさで制する", "内なる力", "本能", "生命力", "自己受容", "精神的強さ", "調和"], "upright": "力ではなく、優しさと忍耐で困難を乗り越えられるとき。自分を信じて。", "reversed": "自信喪失や、感情のコントロールを失いそうな状態。", "love": "根気強く向き合うことで相手の心を開ける。焦らず優しく。", "img": "images/m08.jpg", "catchphrase": "力で抑えるのではなく、愛と意志で自分の本能を扱う。", "story": "力のカードでは、獅子を組み伏せるのではなく、優しく撫でるように描かれます。強引さではなく、忍耐と優しさで困難に向き合う。旅の中で愚者は、本当の強さとは何かを知ることになります。", "age_range": "全世代向け", "current_situation": "今のあなたは、感情のコントロールが試されている状態。嫉妬や不安、もどかしさを感じつつも、力ずくではなく優しさや忍耐で向き合おうとしているとき。すぐに結果を求めず、じっくり向き合う姿勢が問われています。", "place": "ボランティアや動物関連の場、誰かをサポートするような場面での出会い。優しさや忍耐強さが自然と伝わる環境で、じわじわと信頼が育っていくタイミングです。", "symbols": [{"label": "無限記号", "title": "頭上に浮かぶ無限記号（∞）", "text": "尽きることのない精神力、限りない忍耐強さを象徴しています。魔術師の頭上の∞ともつながる、内なる無限の力です。", "x": 22, "y": 12}, {"label": "ライオン", "title": "組み伏せられているライオン", "text": "本能・欲望・怒り・情熱・生命力の象徴。悪者として描かれているのではなく、人間の中にある強いエネルギーそのものを表しています。", "x": 65, "y": 55}, {"label": "ライオンの口を閉じる手", "title": "獅子の口にそっと添えられた手", "text": "力ずくではなく、愛情と忍耐によって本能を治めていることを表しています。本能を消すのではなく、自分の一部として調和させる姿勢の象徴です。", "x": 40, "y": 58}, {"label": "白い衣", "title": "身にまとう白い衣", "text": "混じり気のない、純粋さ・精神性・誠実さを象徴しています。", "x": 35, "y": 35}, {"label": "花の冠と帯", "title": "頭と腰にある花の飾り", "text": "愛・優しさ・生命・自然の象徴。「優しさこそが力になる」というこのカードのテーマを表しています。", "x": 28, "y": 26}, {"label": "山", "title": "背景の山", "text": "試練・成長・克服の象徴です。", "x": 12, "y": 65}, {"label": "緑の自然", "title": "足元に広がる緑", "text": "生命・自然・調和の象徴。内なる本能と自然に調和していることを表しています。", "x": 15, "y": 82}], "work": "力任せに押し通すより、粘り強さと誠実さで信頼を築けるとき。", "connections": {"prev": "戦車「決めた道を、自分の意志で進む。」→ 力「外側だけでなく、自分の内側の本能も扱えるようになる。」", "next": "力「外側だけでなく、自分の内側の本能も扱えるようになる。」→ 隠者「さらに深く、自分自身の答えを探す。」"}}, {"id": "m09", "name_en": "The Hermit", "name_jp": "隠者", "arcana": "major", "number": 9, "keywords": ["内省", "一人の時間", "探求", "経験", "知恵"], "upright": "一度立ち止まり、自分自身と向き合う時間が必要なとき。答えは内側にある。", "reversed": "孤立しすぎる、または助けを求められずに閉じこもる状態。", "love": "今は恋より自分磨きの時期。焦らず内面を整えて。", "img": "images/m09.jpg", "catchphrase": "答えは外ではなく、自分の内側を照らして探す。", "story": "隠者は、旅の折り返し地点。ランプ一つを頼りに、一人静かに歩む姿は、外の世界ではなく自分の内側を照らす時間の大切さを示しています。忙しく進んできた愚者が、初めて立ち止まることを選ぶ場面です。", "age_range": "40代以上向け", "place": "習い事や勉強会、図書館やカフェなど、一人の時間を過ごす場所での出会い。大勢の場よりも、静かな環境でじっくり話せる相手と縁がつながりやすいタイミングです。", "current_situation": "今のあなたは、恋愛よりも自分自身と向き合う時間を大切にしたい段階。一人の時間に充実感を感じていたり、あえて距離を置いて考え事をしているタイミングです。", "symbols": [{"label": "ランタンの星", "title": "ランタンの中の六芒星", "text": "内なる光、叡智の星。ランタンの光はすべてを遠くまで照らすのではなく、足元だけを照らしています。未来のすべてを知る必要はなく、次の一歩が見えればいい、というメッセージです。", "x": 13, "y": 20}, {"label": "グレーのローブ", "title": "身を包む質素な灰色の衣", "text": "外見的な華やかさや世俗的な欲望から距離を置き、内面へ意識を向けていることを表しています。", "x": 40, "y": 52}, {"label": "杖", "title": "もう片方の手にある杖", "text": "支え・経験・自分の足で歩く力の象徴。長い旅を支えてきた経験、これまで積み重ねてきた知恵の証です。", "x": 55, "y": 42}, {"label": "雪山の頂", "title": "立っている雪山の頂上", "text": "試練・精神的成長・高み・探求の象徴。すでに高い場所まで登ってきたことを示す、到達した精神性と孤高の境地を表しています。", "x": 50, "y": 92}], "work": "一人で集中して取り組むことで、質の高い成果につながるとき。深く掘り下げて。", "connections": {"prev": "力「外側だけでなく、自分の内側の本能も扱えるようになる。」→ 隠者「さらに深く、自分自身の答えを探す。」", "next": "隠者「さらに深く、自分自身の答えを探す。」→ 運命の輪「人生の流れそのものが動き始める。」"}}, {"id": "m10", "name_en": "Wheel of Fortune", "name_jp": "運命の輪", "arcana": "major", "number": 10, "keywords": ["転機", "巡り合わせ", "変化", "運命", "循環", "タイミング", "チャンス"], "upright": "流れが大きく動き出すとき。タイミングの巡り合わせを味方につけて。", "reversed": "望まない方向への変化や、流れの停滞を示すことも。", "love": "運命的な出会いや急展開の予感。流れに身を任せてみて。", "img": "images/m10.jpg", "catchphrase": "人生の流れは変わる。今の状態は永遠ではない。", "story": "運命の輪は、努力や意志だけでは動かせない「巡り合わせ」を表すカード。旅の途中で、自分の力を超えた大きな流れがめぐってくることを、愚者はここで知ります。流れに逆らうのではなく、乗ることを学ぶ場面です。", "age_range": "全世代向け", "place": "旅行先や、偶然の予定変更、SNSでのふとしたきっかけなど、予想していなかった場所・タイミングでの出会い。「まさかこんな所で」という運命的な巡り合わせになりそうです。", "current_situation": "今のあなたは、大きな変化やタイミングの巡り合わせを待っている、または実際に流れが動き出している状態。自分の力ではどうにもならない「めぐり合わせ」を感じているときです。", "symbols": [{"label": "四隅の生き物", "title": "輪の四隅に描かれた人・鷲・獅子・牛", "text": "四大福音書の象徴として知られ、四つの固定宮（人＝水瓶座、鷲＝蠍座、獅子＝獅子座、牛＝牡牛座）とも対応づけられます。それぞれが本を読んでおり、変化の中でも学び続けること、運命に振り回されるだけでなく変化から学ぶ姿勢を表しています。", "x": 15, "y": 8}, {"label": "輪の文字と記号", "title": "車輪に刻まれた文字と錬金術記号", "text": "「TARO」や「TORA」の文字が読み取れ、タロットや神聖な知識、宇宙の法則を連想させます。", "x": 50, "y": 48}, {"label": "上のスフィンクス", "title": "輪の頂上に座るスフィンクス", "text": "知恵・謎・判断の象徴。変化の中でも知恵を使う必要があることを示しています。", "x": 50, "y": 15}, {"label": "下る蛇", "title": "輪の脇を下る蛇（テュフォンに関連づけられる存在）", "text": "下降・変化・脱皮、古いものを手放すことを象徴しています。混沌や変化を体現する存在として読まれます。", "x": 18, "y": 48}, {"label": "昇るジャッカル", "title": "輪を昇るジャッカル（アヌビス）", "text": "上昇していく力、運命の巡りに乗って登っていく様子を表しています。", "x": 78, "y": 52}, {"label": "雲", "title": "輪を取り巻く雲", "text": "精神世界・神秘、人間には完全にはコントロールできない大きな流れを象徴しています。", "x": 15, "y": 40}], "work": "自分の努力を超えたところで、状況が大きく動くとき。タイミングを逃さず流れに乗って。", "connections": {"prev": "隠者「さらに深く、自分自身の答えを探す。」→ 運命の輪「人生の流れそのものが動き始める。」", "next": "運命の輪「人生の流れそのものが動き始める。」→ 正義「その流れの中で、自分の選択と結果に向き合う。」"}}, {"id": "m11", "name_en": "Justice", "name_jp": "正義", "arcana": "major", "number": 11, "keywords": ["公平", "バランス", "決断", "真実", "判断", "責任", "結果"], "upright": "冷静で公平な判断が求められるとき。誠実な対応が良い結果につながる。", "reversed": "偏った判断や、不公平な扱いへの不満が生じやすい状態。", "love": "対等な関係を築けるかが鍵。駆け引きより誠実さが吉。", "img": "images/m11.jpg", "catchphrase": "感情に流されず、真実を見て判断する。", "story": "正義は、天秤と剣を持ち、感情に流されず物事を判断する存在。旅を続けてきた愚者は、ここで自分の行いや選択に、誠実に向き合うことを求められます。公平さを大切にすることが、次の一歩を支えてくれます。", "age_range": "30代以上向け", "current_situation": "今のあなたは、フェアな関係でいたいと感じている状態。駆け引きや不公平さに疲れていたり、はっきりさせたいことがあって、誠実な話し合いを望んでいるタイミング。感情より筋道を大事にしたい時期です。", "place": "資格の勉強会やセミナー、士業など「きちんとした」場での出会い。対等な立場で誠実に関わり合える環境から、信頼関係が生まれやすいタイミングです。", "symbols": [{"label": "冠の宝石", "title": "頭上の四角い冠についた宝石", "text": "権威・判断力・公正な裁定の象徴。感情に流されない、明晰な思考を表しています。", "x": 48, "y": 12}, {"label": "剣", "title": "右手に持つまっすぐな両刃の剣", "text": "思考・言葉・判断力、真実を切り分ける力の象徴です。まっすぐに立てられていることで、冷静な判断を表しています。", "x": 28, "y": 25}, {"label": "天秤", "title": "左手に持つ天秤", "text": "公平・バランス・比較の象徴。「好き嫌い」ではなく、事実を比べて判断することを表しています。", "x": 68, "y": 50}, {"label": "赤い衣服", "title": "身にまとう赤い衣", "text": "意志・行動・生命力の象徴です。", "x": 48, "y": 58}, {"label": "紫のカーテン", "title": "背後に垂れる紫のカーテン", "text": "権威・精神性・高い知恵の象徴。表面的なことだけでなく、本質を見ることを表しています。", "x": 50, "y": 8}, {"label": "柱", "title": "左右に立つ柱", "text": "左右対称の構図は、均衡・秩序・判断の場を表しています。女教皇の柱が「相反するものの間にある秘密の知恵」を表すのに対し、正義の柱は「相反するものを比較して公平に判断すること」を象徴します。", "x": 10, "y": 55}, {"label": "緑の布", "title": "カーテンの奥にのぞく緑の布", "text": "調和・成長・バランスの象徴です。", "x": 50, "y": 3}], "work": "公平でフェアな判断が求められる場面。感情より、事実と筋道を大事にして。", "connections": {"prev": "運命の輪「人生の流れそのものが動き始める。」→ 正義「その流れの中で、自分の選択と結果に向き合う。」"}}, {"id": "m12", "name_en": "The Hanged Man", "name_jp": "吊るされた男", "arcana": "major", "number": 12, "keywords": ["停滞", "視点の転換", "忍耐", "受容", "内省", "自発的な制限"], "upright": "今は動けない時期でも、見方を変えることで新しい気づきが得られる。", "reversed": "無駄な我慢や、自己犠牲による疲弊に注意。", "love": "進展のない足踏み状態。今は見守る時期と捉えて。", "img": "images/m12.jpg", "catchphrase": "動かないことで、見えるものがある。", "story": "T字形の木に片足だけ縛られ、逆さに吊るされた男。もう片方の足は曲げられ、両手は背中に回されていますが、その表情はとても穏やかで、頭の周りには光が差しています。完全に動けないわけではないのに、あえて動かない——これは強制された苦しみではなく、自ら受け入れた「停止」。抵抗するのをやめて委ねてみることで、いつもとは逆さまの視点が開け、動いていたときには見えなかったものに気づかされる場面です。", "age_range": "20〜40代向け", "current_situation": "今のあなたは、身動きが取れず足踏みしている状態。連絡を待つしかない、返事が来ない、進展させたくても状況が動かせない、というもどかしいタイミング。今は無理に動かず、待つことも選択肢のひとつです。", "place": "しばらく身動きが取れない状況（多忙・停滞期）の中で、思いがけず出会いが保留されているタイミング。今は探すより、今の環境でご縁が育つのを待つ時期かもしれません。", "symbols": [{"label": "タウ十字の木", "title": "逆さに吊るされている木の形", "text": "T字形の木（タウ十字）は生命の木を表し、犠牲の先にある再生を象徴しています。", "x": 50, "y": 8}, {"label": "頭部の光輪", "title": "頭のまわりに輝く光", "text": "苦しい状況の中でも訪れる、悟りや精神的な目覚めを表しています。", "x": 35, "y": 73}, {"label": "片足で固定された姿勢", "title": "片方の足だけ木に結ばれた姿", "text": "自ら選んで受け入れている制限、自発的な停止であることを示しています。", "x": 45, "y": 25}, {"label": "穏やかな表情", "title": "苦しいはずの体勢でも穏やかな顔", "text": "つらい状況の中にも、見方を変えることで訪れる心の平安を表しています。", "x": 58, "y": 80}, {"label": "組まれた足", "title": "背中で組まれた両足（4の字の形）", "text": "自己犠牲を厭わない、静かな覚悟を象徴するポーズです。", "x": 52, "y": 35}, {"label": "赤と青の衣服", "title": "赤いタイツと青い上着", "text": "赤は行動や情熱、青は静けさや精神性を表すとされ、外側は動けない状況でも内側は落ち着いていることを示しています。", "x": 48, "y": 45}, {"label": "木の葉", "title": "T字の木に茂る緑の葉", "text": "宙づりの状態であっても、木そのものは生きて成長を続けていることを表し、停止の中にも命の営みが続いていることを象徴しています。", "x": 18, "y": 6}], "work": "一旦立ち止まって、視点を変えてみたい時期。無理に結果を急がず、今できる準備に専念して。", "connections": {"next": "吊るされた男「立ち止まることで、見えるものがある。」→ 死神「古い自分を終わらせる。」"}}, {"id": "m13", "name_en": "Death", "name_jp": "死神", "arcana": "major", "number": 13, "keywords": ["終わりと再生", "手放し", "変容", "平等", "浄化", "新しい始まり"], "upright": "一つの区切りを迎え、新しい形へ生まれ変わるとき。手放す勇気が次につながる。", "reversed": "変化を拒み、終わったはずの関係にしがみつく状態。", "love": "関係の転換期。終わりに見えても、新しい形の始まりでもある。", "img": "images/m13.jpg", "catchphrase": "終わることで、新しいものが始まる。", "story": "白い馬に乗った骸骨の騎士が、黒い旗を掲げてゆっくりと進んできます。行く手には倒れた王、跪いて許しを乞う女性、まだ死を恐れず花を差し出す子ども、そして目をそらす司教——立場も年齢も違う人々に、死神は等しく訪れます。けれど旗に描かれているのは純白のバラ。奥には川と、塔の間から昇る太陽も見えます。死神は「死そのもの」ではなく、古い状態が終わり、その先に新しい生命が始まることを伝えるカードです。", "age_range": "全世代向け", "current_situation": "今のあなたは、一つの関係や状況に区切りをつけようとしている、または区切りがつきつつある状態。終わりを認めたくない気持ちもあるけれど、心のどこかでは次に進む準備が始まっているタイミングです。", "place": "何かが終わったあとの新しい環境——引っ越し先、転職先、生活リズムが変わった場所での出会い。過去を手放したタイミングで、自然と新しい出会いの扉が開きます。", "symbols": [{"label": "白馬の骸骨の騎士", "title": "白い馬に乗る骸骨の姿", "text": "地位や立場に関係なく、すべてのものに等しく訪れる終わりを表しています。", "x": 25, "y": 25}, {"label": "黒い旗の白いバラ", "title": "旗に描かれた白いバラ", "text": "死の先にある新しい生命、けがれのない変容の始まりを象徴しています。", "x": 58, "y": 12}, {"label": "倒れる王", "title": "地面に倒れている王", "text": "どれほどの権力や地位があっても、終わりからは逃れられないという平等性を示しています。", "x": 45, "y": 82}, {"label": "昇る太陽", "title": "背景に見える朝日", "text": "一つの終わりの先に、必ず新しい夜明けが訪れることを表しています。", "x": 85, "y": 30}, {"label": "川と小舟", "title": "奥に描かれた川と小舟", "text": "この世とあの世を分ける境界を思わせるモチーフで、大きな移行の途中であることを象徴しています。", "x": 20, "y": 68}, {"label": "跪く女性", "title": "騎士の前でひざまずく女性", "text": "終わりを前にして許しを乞う、あるいは受け入れられずにいる人間の姿を表し、変化への抵抗や戸惑いを象徴しています。", "x": 72, "y": 68}, {"label": "花を差し出す子ども", "title": "騎士に花を渡そうとする子ども", "text": "死をまだ恐れとして知らない無垢さを表し、終わりを特別に恐れる必要はないというメッセージを伝えています。", "x": 88, "y": 80}, {"label": "二つの塔", "title": "遠くに見える塔の間から昇る太陽", "text": "境界を越えた先にある新しい世界への入り口を表し、終わりの先に必ず訪れる再生を象徴しています。", "x": 93, "y": 40}], "work": "一つのやり方や役割に区切りをつけ、新しいスタイルに切り替えるとき。手放すことで次の道が開ける。", "connections": {"prev": "吊るされた男「立ち止まることで、見えるものがある。」→ 死神「古い自分を終わらせる。」", "next": "死神「手放す。」→ 節制「新しく整える。」"}}, {"id": "m14", "name_en": "Temperance", "name_jp": "節制", "arcana": "major", "number": 14, "keywords": ["調和", "バランス", "中庸", "融合", "橋渡し", "適量"], "upright": "異なるもの同士がうまく混ざり合い、心地よいバランスが生まれるとき。", "reversed": "無理な調整や、我慢のしすぎで均衡が崩れそうな状態。", "love": "穏やかで安定した関係。ゆっくりと絆を育てていける時期。", "img": "images/m14.jpg", "catchphrase": "混ぜながら、ちょうどいいところを見つける。", "story": "天使が二つのカップの間で水を行き来させています。ただ混ぜるのではなく、こぼさず、ちょうどいい配分を探りながら。片足は水の中、片足は陸地について、感情や精神の世界と、現実の世界を橋渡ししています。遠くには山と道が続き、道端にはアイリスの花が咲いています。節制は「我慢」でも「抑圧」でもなく、異なるもの同士を少しずつ調整しながら、心地よいバランスへ導いていくカードです。", "age_range": "30代以上向け", "current_situation": "今のあなたは、無理せず、ゆっくりとバランスを探っている状態。急かさず急かされず、お互いのペースに合わせながら関係を育てている、穏やかなタイミング。焦る必要はないと感じているときです。", "place": "落ち着いた雰囲気のカフェや、ヨガ・瞑想など心を整える場での出会い。急かされない、穏やかな空気の中で少しずつ距離が縮まっていくタイミングです。", "symbols": [{"label": "二つのカップの水", "title": "カップの間を行き来する水", "text": "相反するものを混ぜ合わせ、ちょうど良いバランスを探る力を表しています。", "x": 48, "y": 42}, {"label": "片足は水に、片足は地に", "title": "水と陸、両方にかかる足", "text": "感情（水）と現実（地）、両方にまたがりながらバランスを取っていることを示しています。", "x": 48, "y": 85}, {"label": "天使の翼", "title": "背中の大きな翼", "text": "精神性の高さ、メッセンジャーとしての穏やかな役割を象徴しています。", "x": 25, "y": 18}, {"label": "胸の三角と四角", "title": "胸元にある幾何学模様", "text": "精神（三角形）と物質（四角形）、この二つが一つに統合されていることを表しています。", "x": 48, "y": 25}, {"label": "遠くの道と光", "title": "背景に続く道と輝く冠", "text": "焦らず一歩ずつ進んでいった先にある、精神的なゴールを示しています。", "x": 25, "y": 58}, {"label": "アイリスの花", "title": "水辺に咲くアイリス", "text": "希望と伝達の象徴とされる花で、調整の先にある実りや、穏やかなメッセージが届くことを表しています。", "x": 88, "y": 78}, {"label": "遠くの山", "title": "背景に連なる山並み", "text": "調整を重ねた先にたどり着く、精神的なゴールや目標を象徴しています。", "x": 15, "y": 35}], "work": "異なるやり方や意見をうまく調整し、バランスを取りたい場面。焦らず時間をかけて整えて。", "connections": {"prev": "死神「手放す。」→ 節制「新しく整える。」", "next": "節制「自分を整える。」→ 悪魔「自分を縛る欲望や執着に気づく。」"}}, {"id": "m15", "name_en": "The Devil", "name_jp": "悪魔", "arcana": "major", "number": 15, "keywords": ["執着", "誘惑", "依存", "本能", "思い込み", "自己拘束"], "upright": "楽な方に流されたり、強い欲求に引っ張られやすいとき。自覚することが第一歩。", "reversed": "依存や執着から抜け出し、自由を取り戻せる兆し。", "love": "断ち切れない未練や依存的な関係。一度距離を置いて見直しを。", "img": "images/m15.jpg", "catchphrase": "自分を縛っているものに気づく。", "story": "ヤギの頭を持つ悪魔（バフォメット）が、台座の上に鎮座しています。額には精神性が本能に逆転した状態を示す逆五芒星。足元には裸の男女が鎖でつながれていますが、その鎖はよく見るとゆるく、外そうと思えば外せそうな緩さです。男性の尾は燃える炎、女性の尾はブドウの房のような形をしており、それぞれ異なる欲望のかたちを表します。悪魔は「悪いこと」を意味するカードではなく、執着・依存・思い込みという、自分で自分を縛っているものに気づかせるカードです。", "age_range": "20〜30代向け", "current_situation": "今のあなたは、断ち切りたいのに断ち切れない状態。相手のことが良くないと分かっていても離れられない、依存的な関係に心当たりがあるタイミング。まずは自覚することが、抜け出す第一歩になります。", "place": "夜のお店や、刺激の強い遊びの場での出会い。強く惹かれるけれど依存的になりやすい相手との縁が生まれやすいタイミングなので、少し冷静さを持っておきたい場面です。", "symbols": [{"label": "バフォメット", "title": "山羊の頭を持つ悪魔の姿", "text": "本能や物質的な欲望に囚われた状態を象徴する存在です。", "x": 50, "y": 25}, {"label": "逆五芒星", "title": "額に描かれた逆さの星", "text": "精神が物質に支配されてしまっている状態を表しています。", "x": 50, "y": 8}, {"label": "鎖につながれた男女", "title": "悪魔の足元にいる男女", "text": "依存や執着を表しますが、鎖はゆるく、実は外そうと思えば外せるようになっています。囚われは自分の思い込みであることを示唆しています。", "x": 30, "y": 68}, {"label": "小さな角と尻尾", "title": "男女に生えた小さな角と尻尾", "text": "男性の尾は燃える炎、女性の尾はブドウの房のような形をしており、それぞれ情熱的な欲望と快楽的な欲望という異なる誘惑のかたちを象徴しています。", "x": 68, "y": 62}, {"label": "掲げた片手", "title": "悪魔が掲げる片手", "text": "支配や誘惑の力を表すポーズです。", "x": 25, "y": 25}, {"label": "台座", "title": "悪魔と男女が乗る石の台座", "text": "地に足のついた現実的・物質的な基盤を表し、精神よりも物質に重心が置かれている状態を象徴しています。", "x": 50, "y": 78}, {"label": "暗い背景", "title": "画面全体を覆う黒", "text": "光の見えない閉塞感を表す一方で、悪魔のカード自体が「気づき」への入り口でもあることを示しています。", "x": 90, "y": 15}], "work": "楽な方に流されたり、無理な働き方に依存していないか見直したい時期。自覚することが抜け出す第一歩。", "connections": {"prev": "節制「自分を整える。」→ 悪魔「自分を縛る欲望や執着に気づく。」", "next": "悪魔「その鎖、本当に必要？」→ 塔「その鎖ごと、構造が崩れる。」"}}, {"id": "m16", "name_en": "The Tower", "name_jp": "塔", "arcana": "major", "number": 16, "keywords": ["突然の変化", "崩壊", "気づき", "啓示", "浄化", "真実の露出"], "upright": "予期せぬ出来事で状況が一変するとき。ショックの後に本当の道が見えてくる。", "reversed": "変化を恐れて古い価値観にしがみつくこと。", "love": "突然の別れや衝撃的な出来事の暗示。ただし新しい道の入口でもある。", "img": "images/m16.jpg", "catchphrase": "偽りの土台が壊れて、真実が現れる。", "story": "高い塔に雷が落ち、頂上の王冠が吹き飛び、窓からは炎が噴き出しています。塔から投げ出された二人は、これまで築いてきた立場や考え方を手放さざるを得ません。周囲には22個の小さな炎のような粒が降り注ぎ、暗い空を稲妻が切り裂きます。塔は自分が築いてきた価値観や生活の土台、王冠はそれを支配できるという思い込みを表します。塔は単なる「悪い出来事」ではなく、もう必要のない偽りの構造を壊し、本当のものを見せてくれるカードです。", "age_range": "全世代向け", "current_situation": "今のあなたは、思ってもみなかった出来事に振り回されている状態。突然の別れ話、予想外の指摘、当たり前だと思っていた前提が崩れる経験をしているとき。ショックは大きいけれど、同時に「本当のこと」に気づき始めてもいます。", "place": "予期しない出来事がきっかけで生まれる出会い。事故や災害級のハプニング……というほど大げさでなくても、急な予定変更やトラブル対応の場で、思いがけず言葉を交わす相手との縁です。", "symbols": [{"label": "雷に打たれる王冠", "title": "塔の上から落ちる王冠", "text": "誤った権威やエゴが、崩れ去っていく瞬間を象徴しています。", "x": 25, "y": 10}, {"label": "落ちていく二人", "title": "塔から放り出される人物", "text": "積み上げてきたものが、一瞬で崩れてしまう衝撃を表しています。", "x": 25, "y": 50}, {"label": "炎", "title": "塔と窓から噴き出す炎", "text": "古いものを焼き尽くし、浄化していく力を象徴しています。", "x": 45, "y": 25}, {"label": "塔そのもの", "title": "灰色の高い塔", "text": "絶対に揺るがないと思い込んでいた土台そのものが、実は脆いものだったことを示しています。", "x": 48, "y": 55}, {"label": "降り注ぐ粒（ヨッド）", "title": "塔の周囲に散らばる22個の小さな炎のような形", "text": "ヘブライ文字の「ヨッド」を思わせる形で、隠れていた真実や気づきが一気に降り注ぐ様子を象徴しています。", "x": 15, "y": 15}, {"label": "暗い空", "title": "塔を取り巻く黒い空", "text": "何も見えない未知の状態を表し、崩壊の直後はまだ先が見えない不安の時間であることを示しています。", "x": 75, "y": 15}], "work": "予期せぬトラブルや体制の変化に見舞われるとき。壊れた土台から、新しいやり方を築き直す覚悟が必要。", "connections": {"prev": "悪魔「その鎖、本当に必要？」→ 塔「その鎖ごと、構造が崩れる。」", "next": "塔「崩壊。」→ 星「それでも、光は残っている。」"}}, {"id": "m17", "name_en": "The Star", "name_jp": "星", "arcana": "major", "number": 17, "keywords": ["希望", "癒し", "理想", "循環", "自然体", "未来への信頼"], "upright": "静かな希望が心を満たすとき。理想に向かって素直に歩んでいける時期。", "reversed": "理想と現実のギャップに落ち込み、自信を失うこと。", "love": "願いが叶いやすい追い風の時期。前向きな気持ちを大切に。", "img": "images/m17.jpg", "catchphrase": "自分の光をもう一度信じる。", "story": "大きな八芒星の周りに、7つの小さな星が輝いています。裸の女性が、片足は水に、片足は陸につけながら、二つの水瓶から水を注いでいます。片方は池へ、もう片方は大地へ——感情や無意識の世界と、現実の世界の両方を等しく潤していく姿です。遠くには木にとまる鳥、山、緑の草花。星は「すべてがもう解決した」というカードではなく、まだ途中であっても、未来にたしかな光が見えている、という希望を伝えるカードです。", "age_range": "10〜20代向け", "current_situation": "今のあなたは、静かな希望を持って前を向き始めている状態。傷ついた時期を越えて、また誰かを好きになってもいいかな、と思えるようになってきたタイミング。焦らず、素直な気持ちを大切にしたい時期です。", "place": "占いやスピリチュアル系のイベント、癒し系の場での出会い。希望を持ち始めたタイミングで、自然体の自分に共感してくれる相手と縁がつながりやすいです。", "symbols": [{"label": "大きな星と7つの星", "title": "空に輝く大きな星と7つの小さな星", "text": "導きの光、希望の象徴。大きな星は理想を、7つの星は積み重ねてきた歩みを表すとされます。", "x": 48, "y": 10}, {"label": "水を注ぐ女性", "title": "裸のまま水を注ぐ姿", "text": "飾らない自分をさらけ出し、感情を自由に流していくことを表しています。", "x": 48, "y": 50}, {"label": "池と大地", "title": "水を注ぐ先の池と大地", "text": "無意識（水）と意識・現実（大地）、両方に等しく水を注ぐ調和の姿勢を示しています。", "x": 25, "y": 65}, {"label": "後ろの鳥", "title": "背景の木にとまる鳥（トキ）", "text": "エジプトの知恵の神トートを思わせ、静かな叡智を象徴しています。", "x": 85, "y": 32}, {"label": "片膝をつく姿勢", "title": "地面に片膝をついた姿", "text": "謙虚さと、大地への信頼を表しています。", "x": 48, "y": 65}, {"label": "二つの水瓶", "title": "女性が持つ金色の水瓶", "text": "片方は池（無意識・感情）へ、もう片方は大地（現実）へ水を注いでおり、内側にあるものを両方の世界へ循環させていることを表しています。", "x": 30, "y": 52}, {"label": "周囲の草花", "title": "地面いっぱいに咲く小さな花", "text": "静かに育っていく生命力や、これから花開く可能性を象徴しています。", "x": 75, "y": 82}], "work": "焦らず、理想に向けて静かに準備を進めたい時期。小さな希望や手応えを大切に。", "connections": {"prev": "塔「崩壊。」→ 星「それでも、光は残っている。」", "next": "星「希望の光を見つける。」→ 月「まだ見えない部分と向き合う。」"}}, {"id": "m18", "name_en": "The Moon", "name_jp": "月", "arcana": "major", "number": 18, "keywords": ["不安", "曖昧さ", "潜在意識", "直感", "幻想", "本能"], "upright": "はっきりしない状況に不安を感じやすいとき。焦らず様子を見る姿勢が大切。", "reversed": "誤解が解け、状況が少しずつ明らかになっていく兆し。", "love": "相手の気持ちが読めず不安になりやすい時期。思い込みに注意。", "img": "images/m18.jpg", "catchphrase": "今はまだ、全部は見えていない。", "story": "大きな月が、反射した光で地上をぼんやりと照らしています。手前の池からはザリガニが這い出し、犬と狼が月に向かって吠え、その奥には二つの塔と、先の見えない一本の道が続いています。月の光は太陽のように直接輝くのではなく、反射した光——だからこそ、物事がはっきりとは見えません。犬（社会に馴染んだ自分）と狼（野生の本能）は、人の中にある二つの側面。月は単なる「不安」のカードではなく、直感・幻想・無意識が入り混じった、まだ全部は見えていない状態を表しています。", "age_range": "10〜20代向け", "current_situation": "今のあなたは、相手の気持ちがよく分からず、不安や思い込みに振り回されている状態。既読無視や態度の変化に一喜一憂してしまう、はっきりしない関係にモヤモヤしているタイミングです。", "place": "夜の時間帯や、SNS上でのやり取りが中心になる出会い。実際に会う前の段階で、気持ちが揺れ動きやすい、輪郭がはっきりしない関係から始まりそうです。", "symbols": [{"label": "満月と横顔", "title": "空に浮かぶ満月とその中の横顔", "text": "満ちていく感情、無意識の領域を象徴しています。", "x": 50, "y": 15}, {"label": "犬と狼", "title": "池のほとりにいる犬と狼", "text": "飼いならされた本能（犬）と、野生のままの本能（狼）。理性と原始的な恐れの両方を表しています。", "x": 45, "y": 62}, {"label": "ザリガニ", "title": "池から這い出るザリガニ", "text": "無意識の奥底から、少しずつ浮かび上がってくる感情や気づきを象徴しています。", "x": 42, "y": 85}, {"label": "二つの塔", "title": "左右に立つ二つの塔", "text": "現実世界へとつながる入り口、まだ見ぬ世界への門を表しています。", "x": 13, "y": 42}, {"label": "曲がりくねった道", "title": "奥へと続く道", "text": "先の見えない、不確かな道のりを象徴しています。", "x": 70, "y": 68}, {"label": "滴り落ちる光の雫", "title": "月から地上へ降り注ぐ黄色い雫", "text": "直感や気づきが少しずつ意識に届いていく様子を表し、まだ形にならない予感やひらめきを象徴しています。", "x": 30, "y": 30}, {"label": "遠くの山", "title": "塔の向こうに連なる山並み", "text": "まだ足を踏み入れていない未知の領域を表し、月明かりの下で先の見えない道の向こうにも世界が続いていることを示しています。", "x": 55, "y": 30}], "work": "状況がはっきりせず、判断に迷いやすいとき。事実と、不安からくる想像を分けて考えて。", "connections": {"prev": "星「希望の光を見つける。」→ 月「まだ見えない部分と向き合う。」", "next": "月「まだ見えない。」→ 太陽「すべてが見える。」"}}, {"id": "m19", "name_en": "The Sun", "name_jp": "太陽", "arcana": "major", "number": 19, "keywords": ["成功", "喜び", "素直な幸せ", "活力", "真実の開示", "自己表現"], "upright": "明るく満たされた気持ちで物事が順調に進むとき。素直な喜びを味わって。", "reversed": "喜びの一時的な陰りや、はしゃぎすぎによる油断。", "love": "とても良い恋愛運。両想いや幸せな進展を示す明るいカード。", "img": "images/m19.jpg", "catchphrase": "すべてが明るみに出て、自分らしく輝く。", "story": "大きな太陽が、人の顔でこちらを見つめながら光を放っています。裸の子どもが白い馬にまたがり、頭には赤い羽根を飾って、両手を広げてまっすぐに進んでいきます。背景には低い灰色の壁と、太陽に向かって咲く向日葵。月が反射した光であったのに対し、太陽は自ら光を発しています。隠すものは何もなく、子どものように無邪気に、自分自身の光をそのまま放っている——それが太陽のカードです。", "age_range": "全世代向け", "place": "屋外のイベントや、友人同士の集まりなど、明るく開放的な場での出会い。フェスやBBQ、みんなでワイワイするような場面で、自然体のあなたに惹かれる人が現れそうです。", "current_situation": "今のあなたは、素直に楽しい、嬉しいと感じられている明るい状態。恋愛がうまくいっていたり、心から満たされていて、自然と魅力があふれているタイミングです。", "symbols": [{"label": "大きな太陽と顔", "title": "空に輝く太陽とその中の顔", "text": "明晰さ、生命力、意識がはっきりと輝いている状態を表しています。", "x": 45, "y": 15}, {"label": "裸の子供", "title": "白い馬にまたがる裸の子供", "text": "無邪気さ、飾らない喜びを象徴しています。", "x": 35, "y": 68}, {"label": "白馬", "title": "子供が乗る白い馬", "text": "純粋さと、力強くまっすぐな前進を表しています。", "x": 62, "y": 75}, {"label": "向日葵", "title": "背景に並ぶ向日葵", "text": "太陽に向かって伸びる、生命の喜びと明るさを象徴しています。", "x": 20, "y": 42}, {"label": "赤い羽根飾り", "title": "子供の頭にある赤い羽根", "text": "情熱と活力、生き生きとしたエネルギーを表しています。", "x": 32, "y": 52}, {"label": "灰色の壁", "title": "向日葵の手前に連なる低い壁", "text": "これまで乗り越えてきた境界や過去の区切りを表し、その壁を越えた先に今の明るさがあることを示しています。", "x": 50, "y": 72}, {"label": "波打つ光線とまっすぐな光線", "title": "交互に描かれた太陽の光", "text": "まっすぐな光線は理性や意識、波打つ光線は直感や精神性を表すとされ、両方の力が等しく降り注いでいることを象徴しています。", "x": 20, "y": 8}], "work": "努力が実を結び、成果や評価がはっきりと見える明るい時期。自信を持って前に出て。", "connections": {"prev": "月「まだ見えない。」→ 太陽「すべてが見える。」", "next": "太陽「真実が明らかになる。」→ 審判「その真実を受け入れ、生き方を選ぶ。」"}}, {"id": "m20", "name_en": "Judgement", "name_jp": "審判", "arcana": "major", "number": 20, "keywords": ["再生", "目覚め", "決断のとき", "復活", "受容", "呼びかけ"], "upright": "過去を清算し、新しいステージへ進む決断のとき。呼びかけに応える勇気を。", "reversed": "過去への未練で、次の一歩を踏み出せない状態。", "love": "復縁や関係の再スタートの暗示。過去を清算して前へ進める時期。", "img": "images/m20.jpg", "catchphrase": "目覚める。そして、本当の自分として生き直す。", "story": "雲間から現れた天使が、赤い十字の旗がついたラッパを吹き鳴らしています。その音に応えるように、地上の棺から男女と子どもが起き上がり、両手を広げてラッパの方を見上げています。奥には水と山も見えます。審判は「裁かれる」「罰を受ける」カードではありません。人生を振り返り、「本当はどう生きたいのか」に気づき、過去を受け入れたうえで「これからはこう生きる」と決断する——目覚めと再生のカードです。", "age_range": "30代以上向け", "current_situation": "今のあなたは、過去の相手や過去の自分と向き合い直している状態。復縁を考えていたり、以前の失敗を糧に、もう一度チャンスをつかもうとしているタイミング。呼びかけに応える勇気が問われています。", "place": "同窓会やOB・OG会、過去に関わりのあったコミュニティでの再会。以前すれ違った相手と、タイミングを変えてもう一度縁がつながる場面です。", "symbols": [{"label": "ラッパを吹く天使", "title": "空に描かれる天使", "text": "大天使ガブリエルとされ、目覚めへの呼びかけ、魂への合図を象徴しています。", "x": 48, "y": 15}, {"label": "棺から起き上がる人々", "title": "地上の棺とそこから起き上がる人々", "text": "過去からの復活、これまでの経験を糧にした再生を表しています。", "x": 25, "y": 72}, {"label": "十字の旗", "title": "ラッパに掲げられた十字の旗", "text": "精神的な勝利、清算を終えた浄化の状態を象徴しています。", "x": 45, "y": 42}, {"label": "雪山", "title": "背景に連なる雪山", "text": "これまで乗り越えてきた試練、到達した高みを表しています。", "x": 75, "y": 55}, {"label": "灰色の海", "title": "広がる灰色の海", "text": "すべての魂が還っていく場所、集合的な意識を象徴しています。", "x": 50, "y": 85}, {"label": "雲間の天使", "title": "灰色の雲に包まれた天使の姿", "text": "目に見える現実の向こう側からの呼びかけを表し、内側から湧き上がる本当の気持ちのメッセージを象徴しています。", "x": 48, "y": 20}, {"label": "両手を広げる人々", "title": "棺から起き上がり天に手を伸ばす男女と子ども", "text": "強制されてではなく、自ら進んで呼びかけに応えようとする姿勢を表し、過去を受け入れ新しい生き方を選ぶ意志を示しています。", "x": 55, "y": 78}], "work": "過去の経験や以前の仕事のやり方を見直し、新しいステージに進む決断のとき。呼ばれた声に応えて。", "connections": {"prev": "太陽「真実が明らかになる。」→ 審判「その真実を受け入れ、生き方を選ぶ。」", "next": "審判「目覚める。」→ 世界「すべてを統合し、完成する。」"}}, {"id": "m21", "name_en": "The World", "name_jp": "世界", "arcana": "major", "number": 21, "keywords": ["完成", "達成", "統合", "調和", "成就", "一区切り"], "upright": "一つの物語が満足のいく形で完結するとき。努力が報われる充実の時。", "reversed": "あと一歩で完成に届かない、未完了感やもどかしさ。", "love": "関係が一つの理想的な形に到達するサイン。結婚や成就の暗示も。", "img": "images/m21.jpg", "catchphrase": "すべてがひとつにつながり、一つの旅が完成する。", "story": "緑色の花輪の中で、一人の人物が両手に杖を持ち、静かに踊っています。花輪は上下を赤いリボンで結ばれ、四隅には天使・鷲・獅子・牛——風・水・火・地、この世界を構成するすべてのエネルギーが描かれています。完成は「そこで止まる」ことではなく、完成したからこそ自由に動ける、という姿を踊る人物が表しています。世界はここで愚者の旅が一区切りを迎える場所であると同時に、この先また新しい「愚者」の旅が始まる、循環のカードでもあります。", "age_range": "全世代向け", "current_situation": "今のあなたは、一つの関係が理想的な形に近づいている、または大きな区切り（成就・結婚など）を迎えつつある状態。長い道のりを経て、満足のいく着地点が見え始めているタイミングです。", "place": "国際的な場、遠方への旅行、大きな節目のイベントなど、視野が広がる場での出会い。長い目で見て、ゴールにつながるようなご縁が生まれやすいタイミングです。", "symbols": [{"label": "花輪", "title": "中央を囲む楕円形の花輪（月桂樹）", "text": "勝利と達成、一つのサイクルが完成したことを象徴しています。", "x": 15, "y": 50}, {"label": "踊る人物", "title": "花輪の中で踊る人物", "text": "統合された自己、喜びに満ちた完成の状態を表しています。", "x": 48, "y": 45}, {"label": "四隅の生き物", "title": "四隅に描かれた人・鷲・獅子・牛", "text": "運命の輪と同じ四つの存在。四大元素すべてが調和し、統合されていることを示しています。", "x": 15, "y": 8}, {"label": "両手の杖", "title": "両手に持つ二本の杖", "text": "相反する二つの力が、バランスよく統合されていることを表しています。", "x": 30, "y": 48}, {"label": "腰の紫の布", "title": "腰に巻かれた紫の布", "text": "内面と外面、隠された部分とあらわな部分、両方が調和している様子を象徴しています。", "x": 48, "y": 35}, {"label": "花輪を結ぶ赤いリボン", "title": "花輪の上下を結ぶ赤いリボン", "text": "魔術師のカードにある無限大（∞）のマークを思わせる結び目で、終わりと始まりが途切れずつながっていることを象徴しています。", "x": 48, "y": 10}, {"label": "振り返る視線", "title": "進みながら後ろを振り返る人物の姿勢", "text": "これまでの経験を振り返りながらも、体は前へと動き続けている様子を表し、完成が停止ではなく通過点であることを示しています。", "x": 48, "y": 30}], "work": "一つのプロジェクトや役割が、ひとつの形で完成を迎えるとき。次のステージへの区切りとして受け止めて。", "connections": {"prev": "審判「目覚める。」→ 世界「すべてを統合し、完成する。」", "next": "世界「一つの旅が完成する。」→ 愚者「また新しい旅が始まる。」"}}, {"id": "w01", "name_en": "Ace of Wands", "name_jp": "ワンドのエース", "arcana": "wands", "number": 1, "keywords": ["情熱の芽生え", "新しい挑戦", "やる気"], "upright": "何かを始めたいという情熱が湧き上がるとき。第一歩を踏み出す勇気が力になる。", "reversed": "やる気の空回りや、始めたことが長続きしない気配。", "love": "恋への意欲が高まる時期。気になる相手に自分から声をかけてみて。", "img": "images/w01.jpg"}, {"id": "w02", "name_en": "Two of Wands", "name_jp": "ワンドの2", "arcana": "wands", "number": 2, "keywords": ["計画", "展望", "次の一手"], "upright": "今の場所から一歩先を見据え、計画を練るとき。視野を広げてみて。", "reversed": "計画倒れや、決断を先延ばしにしてしまう迷い。", "love": "この先の関係をどうしたいか考えるタイミング。将来を見据えて。", "img": "images/w02.jpg"}, {"id": "w03", "name_en": "Three of Wands", "name_jp": "ワンドの3", "arcana": "wands", "number": 3, "keywords": ["展開", "期待", "先を見る"], "upright": "蒔いた種が育ち始め、次の展開が見えてくるとき。視野の広さが吉。", "reversed": "期待していた展開が遅れたり、見通しが甘かったりする状態。", "love": "関係が少しずつ進展していく兆し。遠距離や未来への期待も吉。", "img": "images/w03.jpg"}, {"id": "w04", "name_en": "Four of Wands", "name_jp": "ワンドの4", "arcana": "wands", "number": 4, "keywords": ["祝福", "安定", "節目の喜び"], "upright": "努力が実を結び、周囲と喜びを分かち合えるとき。安心感のある時期。", "reversed": "祝福のタイミングが少しずれる、または落ち着きに欠ける状態。", "love": "関係の節目を祝えるような、明るく安定した時期。", "img": "images/w04.jpg"}, {"id": "w05", "name_en": "Five of Wands", "name_jp": "ワンドの5", "arcana": "wands", "number": 5, "keywords": ["競争", "意見の衝突", "切磋琢磨"], "upright": "意見のぶつかり合いや競争が起きやすいが、悪いことばかりではない。", "reversed": "無駄な言い争いが長引き、疲弊してしまう状態。", "love": "ちょっとした言い合いや駆け引きが起きやすい時期。感情的にならず冷静に。", "img": "images/w05.jpg"}, {"id": "w06", "name_en": "Six of Wands", "name_jp": "ワンドの6", "arcana": "wands", "number": 6, "keywords": ["勝利", "評価", "自信"], "upright": "努力が認められ、周囲からの評価や成功を実感できるとき。", "reversed": "評価が得られず、自信を失いかけている状態。", "love": "アプローチがうまくいきやすい、恋愛面でも自信を持てる時期。", "img": "images/w06.jpg"}, {"id": "w07", "name_en": "Seven of Wands", "name_jp": "ワンドの7", "arcana": "wands", "number": 7, "keywords": ["防衛", "踏ん張り", "主張"], "upright": "立場を守るために踏ん張らなければならないとき。諦めなければ道は開ける。", "reversed": "プレッシャーに押され、守りきれなくなっている状態。", "love": "ライバルの存在や、気持ちを守るために頑張る場面。粘り強さが吉。", "img": "images/w07.jpg"}, {"id": "w08", "name_en": "Eight of Wands", "name_jp": "ワンドの8", "arcana": "wands", "number": 8, "keywords": ["スピード展開", "急展開", "動き出す運気"], "upright": "物事が一気にスピードアップして動き出すとき。流れに乗って進んで。", "reversed": "急ぎすぎによる行き違いや、物事が滞る状態。", "love": "連絡や進展が一気に動き出す予感。スピード感のある恋。", "img": "images/w08.jpg"}, {"id": "w09", "name_en": "Nine of Wands", "name_jp": "ワンドの9", "arcana": "wands", "number": 9, "keywords": ["粘り強さ", "警戒心", "最後の踏ん張り"], "upright": "これまでの経験を糧に、あと少しの踏ん張りで乗り越えられるとき。", "reversed": "警戒心が強くなりすぎ、心を閉ざしてしまう状態。", "love": "傷ついた経験から慎重になっている状態。少しずつ心を開いて。", "img": "images/w09.jpg"}, {"id": "w10", "name_en": "Ten of Wands", "name_jp": "ワンドの10", "arcana": "wands", "number": 10, "keywords": ["重荷", "責任過多", "やり遂げる"], "upright": "多くの責任を抱え込みながらも、ゴールはもうすぐそこ。", "reversed": "抱えすぎた負担で心身ともに疲れきっている状態。", "love": "関係を続けるための努力や我慢が重なっている状態。一人で抱えすぎないで。", "img": "images/w10.jpg"}, {"id": "w11", "name_en": "Page of Wands", "name_jp": "ワンドのペイジ", "arcana": "wands", "number": 11, "keywords": ["好奇心", "冒険心", "新しい情熱"], "upright": "新しいことに胸を躍らせ、挑戦したい気持ちが芽生えるとき。", "reversed": "計画性のない思いつき行動や、飽きっぽさに注意。", "love": "気になる相手への好奇心が芽生える初々しい恋の予感。", "img": "images/w11.jpg"}, {"id": "w12", "name_en": "Knight of Wands", "name_jp": "ワンドのナイト", "arcana": "wands", "number": 12, "keywords": ["情熱的な行動", "勢い", "スピード"], "upright": "勢いよく行動し、情熱的に物事を進められるとき。", "reversed": "衝動的すぎる行動や、飽きて途中で投げ出してしまう状態。", "love": "情熱的にアプローチしてくる相手、または自分から積極的に動く時期。", "img": "images/w12.jpg"}, {"id": "w13", "name_en": "Queen of Wands", "name_jp": "ワンドのクイーン", "arcana": "wands", "number": 13, "keywords": ["自信", "魅力", "社交性"], "upright": "自信と魅力にあふれ、周囲を惹きつける存在感を発揮できるとき。", "reversed": "自己主張が強すぎて、周りとぶつかりやすい状態。", "love": "自分らしい魅力で相手を惹きつけられる、恋愛でも輝ける時期。", "img": "images/w13.jpg"}, {"id": "w14", "name_en": "King of Wands", "name_jp": "ワンドのキング", "arcana": "wands", "number": 14, "keywords": ["リーダーシップ", "カリスマ性", "決断力"], "upright": "強い意志と行動力でまわりを導ける、頼れる存在になれるとき。", "reversed": "支配的すぎる態度や、独断で突っ走ってしまう状態。", "love": "頼れる年上の相手、またはリードしていく立場になりやすい恋。", "img": "images/w14.jpg"}, {"id": "c01", "name_en": "Ace of Cups", "name_jp": "カップのエース", "arcana": "cups", "number": 1, "keywords": ["新しい感情", "愛の芽生え", "満たされる心"], "upright": "愛情や喜びといった感情が満ちあふれ、新しい始まりを予感させるとき。", "reversed": "感情が空回りしたり、心が満たされないと感じる状態。", "love": "恋愛運が高まる代表的なカード。新しい恋や気持ちの高まりの兆し。", "img": "images/c01.jpg"}, {"id": "c02", "name_en": "Two of Cups", "name_jp": "カップの2", "arcana": "cups", "number": 2, "keywords": ["相思相愛", "絆", "パートナーシップ"], "upright": "心を通わせ合う二人の絆が生まれるとき。信頼関係が深まる時期。", "reversed": "気持ちのすれ違いや、バランスの崩れた関係。", "love": "両想いや相性の良さを示す、恋愛では特に嬉しいカード。", "img": "images/c02.jpg"}, {"id": "c03", "name_en": "Three of Cups", "name_jp": "カップの3", "arcana": "cups", "number": 3, "keywords": ["喜びの共有", "友情", "お祝い"], "upright": "仲間や友人と喜びを分かち合える、楽しく賑やかな時期。", "reversed": "三角関係や、輪の中での孤立感に注意。", "love": "友人を介した出会いや、みんなで楽しめる場での恋の予感。", "img": "images/c03.jpg"}, {"id": "c04", "name_en": "Four of Cups", "name_jp": "カップの4", "arcana": "cups", "number": 4, "keywords": ["無関心", "マンネリ", "内省"], "upright": "目の前にあるものに気づかず、退屈さを感じやすいとき。視点を変えてみて。", "reversed": "新しいチャンスに気づき、心が動き始める兆し。", "love": "マンネリ気味な関係、または相手への関心が薄れている状態。", "img": "images/c04.jpg"}, {"id": "c05", "name_en": "Five of Cups", "name_jp": "カップの5", "arcana": "cups", "number": 5, "keywords": ["喪失感", "後悔", "切り替え"], "upright": "失ったものに気を取られがちだが、まだ残っているものにも目を向けて。", "reversed": "気持ちの整理がつき、前を向き始める兆し。", "love": "失恋やすれ違いによる落ち込み。ただし時間が心を癒してくれる。", "img": "images/c05.jpg"}, {"id": "c06", "name_en": "Six of Cups", "name_jp": "カップの6", "arcana": "cups", "number": 6, "keywords": ["懐かしさ", "再会", "純粋な気持ち"], "upright": "過去の思い出や懐かしい人との再会が心を温めるとき。", "reversed": "過去に囚われすぎて前に進めない状態。", "love": "初恋のような純粋な気持ち、または過去の相手との再会の暗示。", "img": "images/c06.jpg"}, {"id": "c07", "name_en": "Seven of Cups", "name_jp": "カップの7", "arcana": "cups", "number": 7, "keywords": ["選択肢", "幻想", "迷い"], "upright": "多くの選択肢を前に、何が現実的か見極める必要があるとき。", "reversed": "迷いが晴れ、本当に大切なものが見えてくる兆し。", "love": "複数の気になる相手や、理想と現実の間で揺れる恋心。", "img": "images/c07.jpg"}, {"id": "c08", "name_en": "Eight of Cups", "name_jp": "カップの8", "arcana": "cups", "number": 8, "keywords": ["新天地", "見切りをつける", "内面の旅"], "upright": "満たされない何かに気づき、新しい場所へ歩き出す勇気を持つとき。", "reversed": "未練を残したまま立ち去れず、心が揺れている状態。", "love": "今の関係に区切りをつけ、新しい恋へ向かう決断の時期。", "img": "images/c08.jpg"}, {"id": "c09", "name_en": "Nine of Cups", "name_jp": "カップの9", "arcana": "cups", "number": 9, "keywords": ["満足", "願いの成就", "幸福感"], "upright": "願いごとが叶い、満ち足りた幸福感に包まれるとき。", "reversed": "満足しきれず、まだ何かが足りないと感じる状態。", "love": "望んだ関係が叶う、幸せを実感できる時期。", "img": "images/c09.jpg"}, {"id": "c10", "name_en": "Ten of Cups", "name_jp": "カップの10", "arcana": "cups", "number": 10, "keywords": ["家庭円満", "調和", "心からの幸せ"], "upright": "大切な人たちと心から満たされる、穏やかで幸せな時間。", "reversed": "理想の幸せと現実のズレに、小さな不満を感じる状態。", "love": "結婚や将来を見据えられるような、安定した幸せな恋愛関係。", "img": "images/c10.jpg"}, {"id": "c11", "name_en": "Page of Cups", "name_jp": "カップのペイジ", "arcana": "cups", "number": 11, "keywords": ["繊細な感受性", "直感的なメッセージ", "純粋さ"], "upright": "ふとした直感や優しい気持ちが、新しい可能性を運んでくるとき。", "reversed": "感情的になりすぎたり、傷つきやすさが表に出る状態。", "love": "ピュアな気持ちの芽生え、または優しいメッセージが届く予感。", "img": "images/c11.jpg"}, {"id": "c12", "name_en": "Knight of Cups", "name_jp": "カップのナイト", "arcana": "cups", "number": 12, "keywords": ["ロマンチスト", "誠実なアプローチ", "理想の追求"], "upright": "ロマンチックな気持ちで、誠実に理想を追い求められるとき。", "reversed": "理想ばかりが先行し、現実味に欠ける状態。", "love": "誠実でロマンチックなアプローチを受け取れる、恋愛面で嬉しい暗示。", "img": "images/c12.jpg"}, {"id": "c13", "name_en": "Queen of Cups", "name_jp": "カップのクイーン", "arcana": "cups", "number": 13, "keywords": ["共感力", "優しさ", "深い愛情"], "upright": "相手の気持ちに寄り添い、深い愛情で包み込めるとき。", "reversed": "感情に流されすぎたり、共感疲れを起こしやすい状態。", "love": "相手を包み込むような優しさが関係を深める、愛情豊かな時期。", "img": "images/c13.jpg"}, {"id": "c14", "name_en": "King of Cups", "name_jp": "カップのキング", "arcana": "cups", "number": 14, "keywords": ["穏やかな包容力", "感情のコントロール", "思いやり"], "upright": "感情に振り回されず、穏やかに人を支えられる包容力があるとき。", "reversed": "感情を抑え込みすぎて、本音が見えにくい状態。", "love": "落ち着いた大人の余裕を感じさせる相手、または安定した関係。", "img": "images/c14.jpg"}, {"id": "s01", "name_en": "Ace of Swords", "name_jp": "ソードのエース", "arcana": "swords", "number": 1, "keywords": ["明晰な思考", "真実", "新しい視点"], "upright": "頭がクリアになり、物事の本質がはっきり見えるとき。決断に適した時期。", "reversed": "考えが混乱し、判断力が鈍っている状態。", "love": "気持ちがはっきりする、または率直な会話が関係を前進させる時期。", "img": "images/s01.jpg"}, {"id": "s02", "name_en": "Two of Swords", "name_jp": "ソードの2", "arcana": "swords", "number": 2, "keywords": ["迷い", "保留", "バランスを取る"], "upright": "決断を下せず、あえて判断を保留している状態。じっくり考える時間も必要。", "reversed": "先延ばしにしていた決断を、そろそろ下すべきタイミング。", "love": "気持ちを決めかねている状態。答えを急がず、心の声を聞いて。", "img": "images/s02.jpg"}, {"id": "s03", "name_en": "Three of Swords", "name_jp": "ソードの3", "arcana": "swords", "number": 3, "keywords": ["心の痛み", "失望", "傷つき"], "upright": "つらい出来事に心が痛むとき。それでも時間とともに癒えていく。", "reversed": "痛みが和らぎ、少しずつ回復に向かう兆し。", "love": "失恋や誤解によって傷つく暗示。今は無理をせず心を休めて。", "img": "images/s03.jpg"}, {"id": "s04", "name_en": "Four of Swords", "name_jp": "ソードの4", "arcana": "swords", "number": 4, "keywords": ["休息", "静養", "エネルギー回復"], "upright": "動き続けるより、一度立ち止まって心身を休めるべきとき。", "reversed": "休息が足りず、無理を重ねてしまっている状態。", "love": "関係を急がず、一度距離を置いて心を整えたい時期。", "img": "images/s04.jpg"}, {"id": "s05", "name_en": "Five of Swords", "name_jp": "ソードの5", "arcana": "swords", "number": 5, "keywords": ["対立", "勝ち負け", "後味の悪さ"], "upright": "言い争いや対立が起きやすいとき。勝つことより関係を大事にして。", "reversed": "対立が長引き、しこりが残ってしまう状態。", "love": "すれ違いや口論が起きやすい時期。意地を張りすぎないで。", "img": "images/s05.jpg"}, {"id": "s06", "name_en": "Six of Swords", "name_jp": "ソードの6", "arcana": "swords", "number": 6, "keywords": ["移行", "過去からの脱却", "穏やかな前進"], "upright": "つらい状況から少しずつ抜け出し、穏やかな場所へ向かうとき。", "reversed": "過去を引きずったまま、なかなか前に進めない状態。", "love": "つらい経験を乗り越え、少しずつ穏やかな関係へ向かう時期。", "img": "images/s06.jpg"}, {"id": "s07", "name_en": "Seven of Swords", "name_jp": "ソードの7", "arcana": "swords", "number": 7, "keywords": ["駆け引き", "隠しごと", "一人で抱える"], "upright": "一人で解決しようとしたり、本音を隠して立ち回っているとき。", "reversed": "隠していたことが明るみに出やすい状態。", "love": "駆け引きや、本音を言えない関係。素直さが状況を変える鍵。", "img": "images/s07.jpg"}, {"id": "s08", "name_en": "Eight of Swords", "name_jp": "ソードの8", "arcana": "swords", "number": 8, "keywords": ["行き詰まり", "思い込み", "自己制限"], "upright": "自分で自分を縛るような思い込みに囚われているとき。視点を変えれば道は開ける。", "reversed": "思い込みから解放され、視界が開けていく兆し。", "love": "不安や思い込みで身動きが取れない状態。実は選択肢はもっとある。", "img": "images/s08.jpg"}, {"id": "s09", "name_en": "Nine of Swords", "name_jp": "ソードの9", "arcana": "swords", "number": 9, "keywords": ["不安", "悩み", "眠れぬ夜"], "upright": "先の見えない不安に心がすり減ってしまうとき。一人で抱え込まないで。", "reversed": "悩みのピークを越え、少しずつ気持ちが軽くなる兆し。", "love": "相手の気持ちが分からず、思い悩んでしまう時期。話し合いが助けになる。", "img": "images/s09.jpg"}, {"id": "s10", "name_en": "Ten of Swords", "name_jp": "ソードの10", "arcana": "swords", "number": 10, "keywords": ["終焉", "どん底からの再出発", "区切り"], "upright": "一つの物事が完全に終わりを迎えるとき。ここから新しく始められる。", "reversed": "終わりを引き延ばし、区切りをつけられずにいる状態。", "love": "関係の完全な終わり、または大きな区切りを示す。次への準備期間。", "img": "images/s10.jpg"}, {"id": "s11", "name_en": "Page of Swords", "name_jp": "ソードのペイジ", "arcana": "swords", "number": 11, "keywords": ["好奇心旺盛", "情報収集", "率直さ"], "upright": "新しい情報や気づきにアンテナを張り、率直に物事を見られるとき。", "reversed": "噂話や誤解に振り回されやすい状態。", "love": "気になる相手の情報が気になったり、率直なやり取りが生まれる時期。", "img": "images/s11.jpg"}, {"id": "s12", "name_en": "Knight of Swords", "name_jp": "ソードのナイト", "arcana": "swords", "number": 12, "keywords": ["スピード", "率直な行動", "突進力"], "upright": "迷わずまっすぐに突き進む行動力があるとき。ただし性急さには注意。", "reversed": "せっかちすぎる言動で、周囲との摩擦が生まれる状態。", "love": "ストレートなアプローチや、スピーディーに進展する恋の予感。", "img": "images/s12.jpg"}, {"id": "s13", "name_en": "Queen of Swords", "name_jp": "ソードのクイーン", "arcana": "swords", "number": 13, "keywords": ["聡明さ", "客観性", "率直な物言い"], "upright": "感情に流されず、冷静で客観的な判断ができるとき。", "reversed": "言葉が鋭くなりすぎ、相手を傷つけてしまう状態。", "love": "対等でクールな関係、または率直な会話が信頼を築く時期。", "img": "images/s13.jpg"}, {"id": "s14", "name_en": "King of Swords", "name_jp": "ソードのキング", "arcana": "swords", "number": 14, "keywords": ["論理的判断", "公正さ", "知性"], "upright": "感情に左右されず、筋の通った判断で物事を導けるとき。", "reversed": "理屈っぽくなりすぎ、冷たい印象を与えてしまう状態。", "love": "知的で誠実な相手、または筋の通った関係を築ける時期。", "img": "images/s14.jpg"}, {"id": "p01", "name_en": "Ace of Pentacles", "name_jp": "ペンタクルのエース", "arcana": "pentacles", "number": 1, "keywords": ["新しいチャンス", "豊かさの芽生え", "現実的な始まり"], "upright": "実りある新しいチャンスが訪れるとき。地に足のついた第一歩を。", "reversed": "チャンスを逃したり、始めたことが形にならない状態。", "love": "安定につながる出会いや、将来性のある関係の始まり。", "img": "images/p01.jpg"}, {"id": "p02", "name_en": "Two of Pentacles", "name_jp": "ペンタクルの2", "arcana": "pentacles", "number": 2, "keywords": ["バランス", "両立", "柔軟な対応"], "upright": "複数のことをうまくやりくりし、バランスを取っていくとき。", "reversed": "手が回らなくなり、バランスを崩してしまう状態。", "love": "恋と仕事、または複数の気持ちの間でバランスを取っている状態。", "img": "images/p02.jpg"}, {"id": "p03", "name_en": "Three of Pentacles", "name_jp": "ペンタクルの3", "arcana": "pentacles", "number": 3, "keywords": ["協力", "技術", "チームワーク"], "upright": "周囲と協力し合いながら、着実に形にしていけるとき。", "reversed": "連携がうまくいかず、成果につながりにくい状態。", "love": "二人で協力し合いながら関係を築いていける、良い時期。", "img": "images/p03.jpg"}, {"id": "p04", "name_en": "Four of Pentacles", "name_jp": "ペンタクルの4", "arcana": "pentacles", "number": 4, "keywords": ["安定志向", "執着", "守りに入る"], "upright": "今あるものをしっかり守りたい気持ちが強くなるとき。", "reversed": "執着を手放し、少し肩の力を抜けるようになる兆し。", "love": "関係を失いたくないという気持ちから、独占欲が強まりやすい時期。", "img": "images/p04.jpg"}, {"id": "p05", "name_en": "Five of Pentacles", "name_jp": "ペンタクルの5", "arcana": "pentacles", "number": 5, "keywords": ["不安", "孤立感", "苦しい時期"], "upright": "経済的・精神的な不安を感じやすいが、助けはすぐ近くにある。", "reversed": "苦しい時期を抜け出し、支えを得られる兆し。", "love": "孤独感や、すれ違いから来る寂しさを感じやすい時期。一人で抱え込まないで。", "img": "images/p05.jpg"}, {"id": "p06", "name_en": "Six of Pentacles", "name_jp": "ペンタクルの6", "arcana": "pentacles", "number": 6, "keywords": ["分かち合い", "支援", "公平さ"], "upright": "与える人と受け取る人のバランスが取れ、助け合いが生まれるとき。", "reversed": "与えすぎる、または受け取ってばかりでバランスが崩れる状態。", "love": "対等に支え合える関係、または優しさが行き交う嬉しい時期。", "img": "images/p06.jpg"}, {"id": "p07", "name_en": "Seven of Pentacles", "name_jp": "ペンタクルの7", "arcana": "pentacles", "number": 7, "keywords": ["忍耐", "中間評価", "見極め"], "upright": "積み重ねてきた努力の成果を見極め、今後の方向を考えるとき。", "reversed": "焦りから成果を急ぎすぎ、投げ出したくなる状態。", "love": "関係の今後をじっくり見極める時期。焦らず育てていく姿勢が吉。", "img": "images/p07.jpg"}, {"id": "p08", "name_en": "Eight of Pentacles", "name_jp": "ペンタクルの8", "arcana": "pentacles", "number": 8, "keywords": ["熟練", "地道な努力", "スキルアップ"], "upright": "コツコツとした積み重ねが、確かな技術や信頼につながるとき。", "reversed": "努力の方向性がずれていたり、飽きが出てしまう状態。", "love": "誠実に向き合い続けることで、着実に信頼を積み重ねていける時期。", "img": "images/p08.jpg"}, {"id": "p09", "name_en": "Nine of Pentacles", "name_jp": "ペンタクルの9", "arcana": "pentacles", "number": 9, "keywords": ["自立", "充実", "豊かな独り時間"], "upright": "自分の力で築いた豊かさを、一人静かに味わえるとき。", "reversed": "孤独感や、豊かさの中にある物足りなさを感じる状態。", "love": "自立した心地よい関係、または一人の時間も大切にできる余裕のある恋。", "img": "images/p09.jpg"}, {"id": "p10", "name_en": "Ten of Pentacles", "name_jp": "ペンタクルの10", "arcana": "pentacles", "number": 10, "keywords": ["繁栄", "家族", "長期的な安定"], "upright": "長く続く安定と繁栄。家族や大切な人との絆が土台になるとき。", "reversed": "受け継いできたものに、揺らぎや不安が生じる状態。", "love": "結婚や将来を見据えられる、長期的に安定した関係の暗示。", "img": "images/p10.jpg"}, {"id": "p11", "name_en": "Page of Pentacles", "name_jp": "ペンタクルのペイジ", "arcana": "pentacles", "number": 11, "keywords": ["学び", "堅実な一歩", "チャンスへの意欲"], "upright": "新しいことをコツコツ学び、着実に力をつけていけるとき。", "reversed": "計画倒れや、地道な努力を続けられない状態。", "love": "堅実にゆっくり距離を縮めていける、誠実な恋の始まり。", "img": "images/p11.jpg"}, {"id": "p12", "name_en": "Knight of Pentacles", "name_jp": "ペンタクルのナイト", "arcana": "pentacles", "number": 12, "keywords": ["着実さ", "勤勉", "マイペース"], "upright": "地道な努力を、根気強くコツコツ積み重ねていけるとき。", "reversed": "慎重すぎて、チャンスを逃してしまう状態。", "love": "ゆっくりでも着実に信頼を築いていく、堅実で安心できる相手。", "img": "images/p12.jpg"}, {"id": "p13", "name_en": "Queen of Pentacles", "name_jp": "ペンタクルのクイーン", "arcana": "pentacles", "number": 13, "keywords": ["現実的な優しさ", "面倒見の良さ", "豊かな生活力"], "upright": "実生活に根ざした優しさで、周囲を支えられるとき。", "reversed": "世話を焼きすぎたり、現実的すぎて余裕を失う状態。", "love": "生活感のある温かい愛情。安心して頼れる関係が築ける時期。", "img": "images/p13.jpg"}, {"id": "p14", "name_en": "King of Pentacles", "name_jp": "ペンタクルのキング", "arcana": "pentacles", "number": 14, "keywords": ["経済的安定", "現実的な成功", "どっしりとした信頼感"], "upright": "着実な努力の積み重ねが、確かな安定と成功をもたらすとき。", "reversed": "物質面にこだわりすぎ、心の余裕を失っている状態。", "love": "経済的にも精神的にも頼れる、安定感のある相手との関係。", "img": "images/p14.jpg"}];